#!/bin/bash
# watashi v12.3.40dev: the old project name was taken out of this file (names, paths and links only)

source /opt/watashi-manager/common/utils.sh
chown nginx -R . 2>/dev/null || true

# Only set permissions if file exists (generated by jinja)
if [ -f "parts/short-link.conf" ]; then
    set_files_in_folder_readable_to_watashi_common_group parts/short-link.conf
    chmod g+w parts/short-link.conf 2>/dev/null || true
fi

systemctl daemon-reload
systemctl restart watashi-nginx || systemctl start watashi-nginx
